export const developmentViews={
 'glacier-water':[['store','Wet-period budget'],['dry','Dry-period budget'],['release','Supply withdrawal'],['shore','Changing shores']],
 'glacier-energy':[['hydro','Run-of-river hydro'],['lowflow','Low usable flow'],['wind','Wind energy'],['siting','Compare a proposal']],
 'glacier-tourism':[['access','Benefits & pressures'],['erosion','Worn path'],['repair','Managed route'],['rain','Rain on a path']],
 'glacier-conservation':[['intact','Vegetated peat'],['drained','Drained peat'],['restore','Rewet & revegetate'],['monitor','Monitor outcomes']],
 'glacier-thirlmere':[['locate','Locate the landscape'],['geology','Bedrock context'],['ice','Glacial inheritance'],['engineering','Reservoir enlargement'],['photo','Dated photograph']]
};
export const developmentRequirements=Object.fromEntries(Object.entries(developmentViews).map(([k,v])=>[k,v.map(x=>x[0])]));
export const developmentAnimated=(k,v)=>!((k==='glacier-water'&&v==='shore')||(k==='glacier-energy'&&v==='siting')||(k==='glacier-tourism'&&v==='access')||(k==='glacier-conservation'&&v==='monitor')||(k==='glacier-thirlmere'&&['locate','geology','photo'].includes(v)));
export const waterCases={store:{start:1000,inflow:300,supply:200,loss:50},dry:{start:1000,inflow:50,supply:200,loss:50},release:{start:1000,inflow:0,supply:200,loss:0}};
export const waterBudget=({start,inflow,supply,loss})=>start+inflow-supply-loss;
export function thirlmerePhoto(teaching=false){return `<figure style="margin:0 0 20px"><img src="./geography/images/thirlmere-franganillo.jpg" width="1920" height="1080" style="display:block;width:100%;height:auto;border-radius:12px" alt="Thirlmere: open water between wooded slopes and steeper rocky valley sides."><figcaption style="font-size:12px;line-height:1.7;margin-top:12px">Thirlmere Reservoir · 10 August 2012 · <a href="https://commons.wikimedia.org/wiki/File:Thirlmere_Reservoir_(11994195574).jpg" target="_blank" rel="noopener" style="color:inherit">Jorge Franganillo / Flickr</a> · <a href="https://creativecommons.org/licenses/by/2.0/" target="_blank" rel="noopener" style="color:inherit">CC BY 2.0</a> · unchanged.${teaching?' A historical photograph: describe visible water, slopes and woodland. It does not establish rock type, erosion rate or the complete landscape history.':''}</figcaption></figure>`;}
const tx=(x,y,s,z=13)=>`<text x="${x}" y="${y}" font-size="${z}">${s}</text>`;
const line=(p,c='#badfe6',w=3,rest='')=>`<path d="${p}" stroke="${c}" stroke-width="${w}" fill="none" ${rest}/>`;
const ar=(x,y,a,b)=>line(`M${x} ${y}L${a} ${b}`,'#efa18b',3,'marker-end="url(#devArrow)"');
const dot=(x,y,r=5,c='#e7c599')=>`<circle cx="${x}" cy="${y}" r="${r}" fill="${c}"/>`;
const box=(x,y,w,h,s)=>`<rect x="${x}" y="${y}" width="${w}" height="${h}" rx="8" fill="#365267" stroke="#9bb8c1"/>`+tx(x+10,y+24,s,12);
const wrap=(b,c)=>`<svg class="geo-scene" viewBox="0 0 440 350" role="img" aria-label="${c.replaceAll('&','&amp;').replaceAll('"','&quot;')}"><defs><linearGradient id="devRock" x2="0" y2="1"><stop stop-color="#adb49e"/><stop offset="1" stop-color="#748b80"/></linearGradient><marker id="devArrow" viewBox="0 0 10 10" refX="8" refY="5" markerWidth="5" markerHeight="5" orient="auto"><path d="M0 0L10 5 0 10Z" fill="#efa18b"/></marker></defs><g font-family="sans-serif" fill="#edf2ed">${b}</g></svg><p class="geo-caption">${c}</p>`;
const rain=t=>Array.from({length:10},(_,i)=>line(`M${35+i*34} ${65+(t*60+i*8)%65}l-4 9`,'#b9dce6',2)).join('');
export function developmentScene(k,selected,t=0){const opts=developmentViews[k];if(!opts)return '';const v=opts.some(x=>x[0]===selected)?selected:opts[0][0];t=Math.min(1,Math.max(0,Number(t)||0));if(!developmentAnimated(k,v))t=0;if(k==='glacier-thirlmere'&&v==='photo')return thirlmerePhoto(true);let b='',c='';
 if(k==='glacier-water'){
  if(v==='shore'){b=tx(25,30,'CONCEPTUAL VALLEY · shoreline change')+'<path d="M20 90L115 255H330L420 90V325H20Z" fill="url(#devRock)"/><path d="M75 180H370L330 255H115Z" fill="#75a8ba" opacity=".75"/>'+line('M100 230H345','#f0d5b8',3,'stroke-dasharray="6 5"')+tx(25,75,'Higher water can inundate land',14)+tx(25,310,'Dashed: earlier water level · no measured scale',12);c='A raised water level changes the shoreline and can inundate land uses and habitats. The section illustrates a mechanism, not actual Thirlmere levels, a surveyed valley or permission for a new scheme.';}
  else{const a=waterCases[v],end=waterBudget(a),level=1000+(end-1000)*t,y=270-level*.12;b=tx(25,30,'INVENTED STORE · one defined period')+'<path d="M70 90V275H270V90" fill="none" stroke="#a9bec6" stroke-width="4"/>'+`<rect x="73" y="${y}" width="194" height="${275-y}" fill="#7eacbd"/>`+tx(90,235,`${Math.round(level)}m³`,20)+ar(25,120,65,120)+ar(275,200,370,200)+tx(285,155,`In: ${a.inflow}m³`,12)+tx(285,180,`Supply: ${a.supply}m³`,12)+tx(285,230,`Other: ${a.loss}m³`,12)+tx(25,310,`${a.start} + ${a.inflow} − ${a.supply} − ${a.loss} = ${end}m³`,16);c=`Invented budget: start${a.start}m³ + inflow${a.inflow}m³ − supply${a.supply}m³ − other losses${a.loss}m³ = ${end}m³. The animation moves from start to final storage for one hypothetical period; no real reservoir measurements, forecast or unlimited capacity are implied.`;}
 }
 if(k==='glacier-energy'){
  if(v==='siting'){b=tx(25,30,'JUDGE A PROPOSAL · evidence needed')+box(25,75,185,55,'Resource: flow / wind')+box(230,75,185,55,'Ecology and landscape')+box(25,165,185,55,'Access / grid / costs')+box(230,165,185,55,'Community and needs')+tx(25,295,'No universal best site · compare alternatives',13);c='A renewable-energy judgement weighs resource, ecology, landscape, infrastructure, cost and community evidence. This static framework is not a site approval or a calculated benefit score.';}
  else if(v==='wind'){b=tx(25,30,'WIND → ROTOR → GENERATOR')+'<path d="M20 285L130 245 240 270 420 215V325H20Z" fill="url(#devRock)"/><path d="M235 270V130" stroke="#cbd8d8" stroke-width="6"/>'+`<g transform="rotate(${t*360} 235 130)"><path d="M235 130V65M235 130L290 163M235 130L180 163" stroke="#e2e9e8" stroke-width="7"/></g>`+dot(235,130,9,'#e8cab0')+ar(35,105,150,105)+tx(25,310,'Variable wind and operating conditions → variable output',12);c='Moving air turns a rotor coupled to generation equipment. Variable wind and operating limits affect output; tracks, construction and visibility can change upland landscapes. Rotation is symbolic, not a measured turbine speed.';}
  else{const low=v==='lowflow';b=tx(25,30,'RUN-OF-RIVER HYDRO · return water downstream')+'<path d="M20 100L300 270H420V325H20Z" fill="url(#devRock)"/>'+line('M20 97L315 268H420','#83b7c6',low?5:11)+line('M105 150L290 210V260H370','#bedfe8',5)+box(270,190,115,60,'Turbine / generator')+`<g transform="rotate(${t*(low?80:360)} 295 220)"><path d="M295 204V236M279 220H311" stroke="#eac99e" stroke-width="4"/></g>`;for(let i=0;i<(low?2:6);i++)b+=dot(110+(t*180+i*35)%180,150+((t*180+i*35)%180)/3,3,'#e4eef0');b+=tx(25,310,low?'Less usable flow · maintain stream needs':'Divert some flow · usable head · return water',12);c=low?'Lower usable flow can reduce hydro output, with environmental stream requirements and operating limits. This is a conceptual comparison, not the measured performance of Stickle Ghyll.':'Some flow enters an intake/pipe, transfers energy through a height difference to turbine and generator, then returns downstream. A run-of-river scheme need not create a huge new reservoir; habitats and bypassed flow still need consideration.';}
 }
 if(k==='glacier-tourism'){
  if(v==='access'){b=tx(25,30,'TOURISM · different users, different effects')+box(25,80,185,65,'Income / employment')+box(230,80,185,65,'Access / wellbeing')+box(25,180,185,65,'Traffic / services')+box(230,180,185,65,'Habitats / erosion')+tx(25,310,'Seasonality and distribution of benefits matter',13);c='Tourism can support local income, services and recreation while increasing traffic and environmental pressure. These are possible effects to investigate, not quantified visitor statistics.';}
  else{const repair=v==='repair';b=tx(25,30,'SLOPE VIEW · people, rain and path condition')+'<path d="M20 130L335 285H420V325H20Z" fill="url(#devRock)"/>'+line('M50 145L320 277',repair?'#c4c7bf':'#d4b791',repair?13:22+t*17)+rain(t);for(let i=0;i<5;i++){const x=70+(t*210+i*42)%230;b+=dot(x,150+(x-50)*.48,3,repair?'#e9d9ba':'#a4cdda');}if(repair){b+=line('M155 200L220 175','#a8d7e5',4)+ar(170,195,210,180)+tx(25,90,'Drain water safely · durable surface · restore edges',12);}else b+=ar(150,200,250,250)+tx(25,90,v==='rain'?'Concentrated runoff can carry exposed soil':'Trampling and avoidance can widen bare ground',12);c=repair?'A durable route, suitable cross-drainage and restored edges can reduce path erosion and encourage people to stay on the path. Maintenance and monitoring remain necessary; poorly designed drainage can move the problem elsewhere.':v==='rain'?'Rain on a compacted, exposed route can concentrate runoff and carry sediment downslope. Slope, soil and weather interact with visitor pressure; the replay is not a measured erosion rate.':'Repeated trampling and avoidance of rough sections can remove vegetation and widen damage. Water can then mobilise exposed sediment. This loop illustrates interaction, not a universal damage-per-visitor value.';}
 }
 if(k==='glacier-conservation'){
  if(v==='monitor'){b=tx(25,30,'MONITOR BEFORE / AFTER · add comparisons')+box(25,75,185,55,'Vegetation and habitat')+box(230,75,185,55,'Water level / quality')+box(25,170,185,55,'Erosion / sediment')+box(230,170,185,55,'Costs / users / access')+tx(25,300,'Baseline + follow-up + context · not invented results',12);c='Monitor relevant baseline and follow-up conditions, with suitable comparisons and context. A green illustration alone is not measured ecological, carbon or hydrological success.';}
  else{const intact=v==='intact',restore=v==='restore';b=tx(25,30,'PEAT CROSS-SECTION · symbolic water table')+'<path d="M20 160H420V310H20Z" fill="#8b8472"/><path d="M20 160H420" stroke="#b8c7a4" stroke-width="10"/>'+rain(t);const level=intact?180:restore?235-t*50:235;b+=line(`M25 ${level}H415`,'#a9d7e5',3,'stroke-dasharray="6 5"');if(!intact)b+='<path d="M200 160V255H240V160" fill="#304d60"/>';if(restore)b+=`<path d="M198 ${253-t*85}H242V255H198Z" fill="#c9b28f"/>`;for(let i=0;i<8;i++)b+=`<path d="M${40+i*47} 160v-${intact?12:restore?3+t*9:3}" stroke="#c4d4ac" stroke-width="3"/>`;b+=dot(80+t*100,170,3,'#c3e0e7')+tx(25,335,intact?'Protective vegetation · high water table':restore?'Suitable drain blocking · rising local water table':'Drainage can lower water levels and expose peat',12);c=intact?'Vegetated wet peat can support habitat and protect a carbon store. High water tables do not mean zero runoff or unlimited flood storage; this is a conceptual section.':restore?'Selected drain blocking and revegetation can raise local water levels and stabilise damaged peat. Recovery needs suitable design, time and monitoring. The whole catchment is not assumed to be peat, nor all flooding prevented.':'Artificial drainage can lower peat water levels, while vegetation loss can expose surfaces to erosion. Conditions and management vary; the section is not an observed Armboth water-level record.';}
 }
 if(k==='glacier-thirlmere'){
  if(v==='locate'){b=tx(25,30,'CENTRAL LAKE DISTRICT · selected relationships')+box(25,65,180,45,'NW England / Cumbria')+'<path d="M170 140Q125 200 160 280Q190 300 205 240L210 150Z" fill="#7eafc0"/>'+dot(300,170,8)+tx(225,145,'Helvellyn massif',13)+tx(25,220,'Thirlmere valley',13)+ar(230,85,230,55)+tx(225,45,'N',13)+tx(25,325,'Generalised locator · not an OS or geology map',12);c='Thirlmere lies beside Helvellyn in the central Lake District, Cumbria, northwest England. Relative positions are generalised, not surveyed distances, geological boundaries or an OS-map extract.';}
  else if(v==='geology'){b=tx(25,30,'GEOLOGICAL CONTEXT · selected rock types')+'<path d="M20 260L130 130 220 195 310 90 420 260V320H20Z" fill="url(#devRock)"/>'+tx(25,70,'Borrowdale Volcanic Group',17)+tx(25,285,'Ancient lavas and tuffs · not original volcanic cones',12);c='Ancient volcanic rocks, including lavas and tuffs, underlie much of this craggy area. The fells are eroded remnants shaped by later processes, not the intact original volcanoes. This schematic does not map individual units.';}
  else{const engineered=v==='engineering',left=engineered?105:100-t*35,right=440-left,bed=engineered?285:235+t*50;b=tx(25,30,engineered?'HUMAN CHANGE · enlarged water body':'INHERITED RELIEF · moving ice excavates')+`<path d="M20 90L${left} 180Q${left} ${bed} 220 ${bed}T${right} 180L420 90V325H20Z" fill="url(#devRock)"/>`;if(engineered){const h=260-t*65;b+=`<path d="M105 ${h}H335V285H105Z" fill="#78aebf"/><path d="M328 150H348V285H328Z" fill="#b6c1c1"/>`+line('M110 260H330','#eed5bd',2,'stroke-dasharray="5 5"')+tx(25,80,'Historical supply connection:1894',13);}else b+=`<path d="M${left} 180H${right}Q${right} ${bed} 220 ${bed}T${left} 180Z" fill="#b3d5e2"/>`+ar(220,180,220,250);c=engineered?'The national park describes reservoir enlargement and an aqueduct connected to Manchester in1894. Engineering strongly changed the modern water body and shores, while geology and glaciation explain wider relief. The section is not an actual dam design or measured water-level history.':'Glacial erosion enlarged and deepened an older valley landscape, with geology influencing its form. After ice loss, rivers, weathering and slope processes continued. This is a generalised reconstruction, not a dated model of actual Thirlmere erosion.';}
 }
 return wrap(b,c);
}
